"""
Token Usage Monitoring Tool

A polished mini-tool for monitoring token usage in long-running coding sessions.
Reads a session report, computes thresholds, and generates:
- Terminal-friendly alert summary
- Lightweight HTML dashboard

Thresholds: 75% (High Warning), 90% (Critical), 95% (Emergency)
"""

import json
import sys
import argparse
from pathlib import Path
from datetime import datetime

# Threshold configuration
THRESHOLDS = {
    75: {"level": "high", "emoji": "🔶", "label": "High Warning"},
    90: {"level": "critical", "emoji": "🔴", "label": "Critical Warning"},
    95: {"level": "emergency", "emoji": "🚨", "label": "Emergency"}
}


def load_session_report(filepath: str) -> dict:
    """Load and parse the session report JSON file."""
    with open(filepath, 'r') as f:
        return json.load(f)


def calculate_usage(report: dict) -> dict:
    """Calculate token usage statistics."""
    tokens_used = report.get("tokens_used", 0)
    token_limit = report.get("token_limit", 1)

    percentage = (tokens_used / token_limit) * 100
    tokens_remaining = token_limit - tokens_used

    return {
        "tokens_used": tokens_used,
        "token_limit": token_limit,
        "percentage": percentage,
        "tokens_remaining": tokens_remaining
    }


def get_threshold_status(percentage: float) -> tuple:
    """Determine which threshold level the usage has reached."""
    threshold_met = None
    threshold_value = 0

    for thresh in sorted(THRESHOLDS.keys()):
        if percentage >= thresh:
            threshold_met = thresh
            threshold_value = THRESHOLDS[thresh]

    if threshold_met is None:
        return None, {"level": "normal", "emoji": "🟢", "label": "Normal"}

    return threshold_met, threshold_value


def create_progress_bar(percentage: float, width: int = 25) -> str:
    """Create a box-style progress bar using ▰ and ▱ characters."""
    filled = int(percentage / 100 * width)
    filled = max(0, min(width, filled))
    empty = width - filled

    bar = "▰" * filled + "▱" * empty
    return bar


def format_terminal_alert(report: dict, usage: dict, threshold_info: tuple) -> str:
    """Format a terminal-friendly alert summary."""
    marker = report.get("marker", "NO_MARKER")
    session_name = report.get("session_name", "Unknown Session")
    percent = usage["percentage"]
    threshold_level, status = threshold_info

