    lines.append(f"  TOKEN USAGE ALERT - {session_name}")
    lines.append("=" * 50)
    lines.append("")

    # Progress bar with emoji
    bar = create_progress_bar(percent)
    lines.append(f"{status['emoji']} {bar} {percent:.1f}%")
    lines.append(f"{usage['tokens_used']:,} / {usage['token_limit']:,} tokens used")
    lines.append("")

    # Status line
    lines.append(f"⚠️  Status: {status['label']}")
    lines.append(f"💡 Remaining: {usage['tokens_remaining']:,} tokens")
    lines.append("")

    # Threshold warnings
    lines.append("📊 Threshold Status:")
    for thresh in sorted(THRESHOLDS.keys()):
        thresh_info = THRESHOLDS[thresh]
        if percent >= thresh:
            lines.append(f"   {thresh_info['emoji']} {thresh}% - {thresh_info['label']} ✓")
        else:
            lines.append(f"   ⚪  {thresh}% - {thresh_info['label']} (not reached)")
    lines.append("")

    # Recommendations based on level
    lines.append("🔧 Recommendations:")
    if status["level"] == "emergency":
        lines.append("   ⚠️  CRITICAL: Save your work immediately!")
        lines.append("   ⚠️  Start a new session for new tasks")
        lines.append("   ⚠️  Contact support for token refill")
    elif status["level"] == "critical":
